import json, os, glob, collections, datetime

files = sorted(glob.glob(os.path.expanduser('~/.claude/projects/*/*.jsonl')),
               key=lambda p: os.path.getmtime(p), reverse=True)[:50]

tools = collections.Counter()
mcp = collections.Counter()
skills = collections.Counter()
cmds = collections.Counter()
hooks = collections.defaultdict(list)
denials = collections.Counter()
denial_kinds = collections.defaultdict(collections.Counter)
tool_use_by_id = {}
denial_records = []  # (tool_use_id, kind)
times = []

for f in files:
    with open(f, errors='replace') as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                o = json.loads(line)
            except Exception:
                continue
            ts = o.get('timestamp')
            if ts:
                times.append(ts)
            t = o.get('type')
            if t == 'assistant':
                for c in (o.get('message', {}) or {}).get('content', []) or []:
                    if isinstance(c, dict) and c.get('type') == 'tool_use':
                        n = c.get('name', '')
                        tools[n] += 1
                        tool_use_by_id[c.get('id')] = (n, c.get('input', {}))
                        if n.startswith('mcp__'):
                            mcp['__'.join(n.split('__')[:2])] += 1
                        if n == 'Skill':
                            skills[str((c.get('input') or {}).get('skill'))] += 1
            elif t == 'user':
                kind = o.get('toolDenialKind')
                content = (o.get('message', {}) or {}).get('content')
                if isinstance(content, list):
                    for c in content:
                        if isinstance(c, dict) and c.get('type') == 'tool_result' and kind:
                            denial_records.append((c.get('tool_use_id'), kind))
                        if isinstance(c, dict) and c.get('type') == 'text' and '<command-name>' in str(c.get('text', '')):
                            txt = c['text']
                            i = txt.find('<command-name>')
                            j = txt.find('</command-name>')
                            cmds[txt[i+14:j]] += 1
                elif isinstance(content, str) and '<command-name>' in content:
                    i = content.find('<command-name>')
                    j = content.find('</command-name>')
                    cmds[content[i+14:j]] += 1
            elif t == 'attachment':
                a = o.get('attachment', {}) or {}
                if str(a.get('type', '')).startswith('hook_'):
                    hooks[(a.get('hookName'), a.get('hookEvent'), a.get('type'))].append(
                        (a.get('durationMs'), a.get('timedOut'), a.get('timeoutMs')))

print('files scanned:', len(files))
print('window:', min(times)[:10] if times else '?', '->', max(times)[:10] if times else '?')
print('\n== tool counts (top 25) ==')
for k, v in tools.most_common(25):
    print(f'{v:6d}  {k}')
print('\n== mcp servers ==', dict(mcp))
print('== Skill tool dispatches ==', dict(skills))
print('== slash commands ==', dict(cmds))
print('\n== hooks ==')
for k, v in hooks.items():
    ds = [d for d, _, _ in v if isinstance(d, (int, float))]
    ds.sort()
    print(k, 'runs=', len(v), 'median=', ds[len(ds)//2] if ds else None, 'max=', max(ds) if ds else None,
          'timedOut=', sum(1 for _, t, _ in v if t))

print('\n== denials ==')
for tid, kind in denial_records:
    n, inp = tool_use_by_id.get(tid, ('<unknown>', {}))
    if n == 'Bash':
        cmd = str(inp.get('command', ''))[:80]
        key = 'Bash: ' + ' '.join(cmd.split()[:2])
    else:
        key = n
    denials[key] += 1
    denial_kinds[key][kind] += 1
for k, v in denials.most_common(30):
    print(f'{v:4d}  {k}   {dict(denial_kinds[k])}')

